def words_with(node, prefix):
    for ch in prefix:
        if ch not in node:
            return []
        node = node[ch]
    found = []

    def walk(current, built):
        if "$" in current:
            found.append(built)
        for ch in sorted(k for k in current if k != "$"):
            walk(current[ch], built + ch)

    walk(node, prefix)
    return found

