    for item in ids:
        if item not in seen:
            seen.add(item)
            kept.append(item)
    return kept

def top_k(rows, k):
    kept = []
    for doc_id, score in rows:
        heapq.heappush(kept, Rank(score, doc_id))
        if len(kept) > k:
            heapq.heappop(kept)
    return [item.doc_id for item in sorted(kept, reverse=True)]

