def best_unique(rows, k):
    if k <= 0:
        return []
    seen = set()
    unique = []
    for doc_id, score in rows:
        if doc_id not in seen:
            seen.add(doc_id)
            unique.append((doc_id, score))
    ranked = sorted(unique, key=lambda row: row[1], reverse=True)
    return [doc_id for doc_id, score in ranked[:k]]

