def insertion_sort(values):
    result = list(values)
    for i in range(1, len(result)):
        held = result[i]
        j = i - 1
        while j >= 0 and result[j] > held:
            result[j + 1] = result[j]
            j -= 1
        result[j + 1] = held
    return result

def lower_bound(values, target):
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def pair_sum(values, target):
    left, right = 0, len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return left, right
        if total < target:
            left += 1
        else:
            right -= 1
    return None

def window_sums(values, width):
    if width <= 0 or width > len(values):
        return []
    total = sum(values[:width])
    totals = [total]
    for right in range(width, len(values)):
        total += values[right] - values[right - width]
        totals.append(total)
    return totals

def balanced(text):
    stack = []
    closing = {')': '(', ']': '[', '}': '{'}
    for char in text:
        if char in '([{':
            stack.append(char)
        elif char in closing:
            if not stack or stack.pop() != closing[char]:
                return False
    return not stack

def factorial(n):
    if n < 0:
        raise ValueError("n must be nonnegative")
    if n == 0:
        return 1
    smaller = factorial(n - 1)
    return n * smaller

def subsets_within(items, limit):
    if any(value < 0 for value in items):
        raise ValueError("costs must be nonnegative")
    answers = []
    def visit(i, chosen, total):
        if total > limit:
            return
        if i == len(items):
            answers.append(chosen)
            return
        visit(i + 1, chosen, total)
        visit(i + 1, chosen + [items[i]], total + items[i])
    visit(0, [], 0)
    return answers

